targets as (select case_number, '10000000-0000-4000-8000-000000000001'::uuid as account_id, ('20000000-0000-4000-8000-' || lpad(case_number::text, 12, '0'))::uuid as landing_page_id, expected from specimens
 union all select 0, '10000000-0000-4000-8000-000000000002'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, '[]'::jsonb),
history as (select md5(s.case_number::text || ':' || f.ordinality::text)::uuid as id, '10000000-0000-4000-8000-000000000001'::uuid as account_id,
 ('20000000-0000-4000-8000-' || lpad(s.case_number::text,12,'0'))::uuid as landing_page_id, f.ordinality::bigint as revision_number, shapes.snapshot as generation_context_snapshot_json
 from specimens s cross join lateral jsonb_array_elements_text(s.shape_indexes) with ordinality f(shape_index, ordinality)
 join shapes on shapes.shape_index = f.shape_index::integer),
results as (select targets.case_number, targets.expected,
 coalesce(jsonb_agg(selected.revision_number order by selected.revision_number) filter (where selected.id is not null), '[]'::jsonb) as actual,
 count(selected.id) as snapshots,
 coalesce(bool_and(selected.account_id = targets.account_id and selected.landing_page_id = targets.landing_page_id and selected.latest_materialization_id = (select h.id from history h where h.account_id = targets.account_id and h.landing_page_id = targets.landing_page_id order by h.revision_number desc limit 1)), true) as tenant_and_latest
 from targets left join lateral (
-- Eligibility only: model facts must be an array even for binding facts.
-- Strict paths do not unwrap arrays; value:null is present, invalid offers qualify.
with latest as (
  select id, revision_number
  from history
  where account_id = targets.account_id and landing_page_id = targets.landing_page_id
  order by revision_number desc
  limit 1
), selected as (
  (select id, revision_number
   from history
   where account_id = targets.account_id and landing_page_id = targets.landing_page_id
     and jsonb_typeof(generation_context_snapshot_json #> '{generationContext,modelContext,facts}') = 'array'
    and (
      jsonb_path_exists(generation_context_snapshot_json, 'strict $.generationContext.modelContext.facts[*] ? (@.type() == "object" && @.fieldKey.type() == "string" && @.fieldKey == "funnel_stage" && exists(@.value))', '{}'::jsonb, true)
      or jsonb_path_exists(generation_context_snapshot_json, 'strict $.generationContext.bindingFacts[*] ? (@.type() == "object" && @.fieldKey.type() == "string" && @.fieldKey == "funnel_stage" && exists(@.value))', '{}'::jsonb, true)
    )
   order by revision_number asc
   limit 1)
  union
  (select id, revision_number
   from history
   where account_id = targets.account_id and landing_page_id = targets.landing_page_id
     and jsonb_typeof(generation_context_snapshot_json #> '{generationContext,modelContext,facts}') = 'array'
    and (
      jsonb_path_exists(generation_context_snapshot_json, 'strict $.generationContext.modelContext.facts[*] ? (@.type() == "object" && @.fieldKey.type() == "string" && @.fieldKey == "transaction_intent" && exists(@.value))', '{}'::jsonb, true)
      or jsonb_path_exists(generation_context_snapshot_json, 'strict $.generationContext.bindingFacts[*] ? (@.type() == "object" && @.fieldKey.type() == "string" && @.fieldKey == "transaction_intent" && exists(@.value))', '{}'::jsonb, true)
    )
   order by revision_number asc
   limit 1)
  union
  (select id, revision_number
   from history
   where account_id = targets.account_id and landing_page_id = targets.landing_page_id
     and jsonb_typeof(generation_context_snapshot_json #> '{generationContext,modelContext,facts}') = 'array'
    and (
      jsonb_path_exists(generation_context_snapshot_json, 'strict $.generationContext.modelContext.facts[*] ? (@.type() == "object" && @.fieldKey.type() == "string" && (@.fieldKey == "landing_page_offering_scope" || @.fieldKey == "primary_service_or_offer") && exists(@.value))', '{}'::jsonb, true)
      or jsonb_path_exists(generation_context_snapshot_json, 'strict $.generationContext.bindingFacts[*] ? (@.type() == "object" && @.fieldKey.type() == "string" && (@.fieldKey == "landing_page_offering_scope" || @.fieldKey == "primary_service_or_offer") && exists(@.value))', '{}'::jsonb, true)
    )
   order by revision_number asc
   limit 1)
  union
  select id, revision_number from latest
)
select m.id, m.account_id, m.landing_page_id, m.revision_number,
       m.generation_context_snapshot_json, latest.id as latest_materialization_id
from selected
join history m
  on m.id = selected.id and m.revision_number = selected.revision_number
 and m.account_id = targets.account_id and m.landing_page_id = targets.landing_page_id
cross join latest
order by m.revision_number asc
) selected on true group by targets.case_number, targets.expected)
select count(*) as cases, count(*) filter (where actual <> expected or snapshots > 4 or not tenant_and_latest) as failures,
 max(snapshots) as max_snapshots, coalesce(jsonb_agg(case_number) filter (where actual <> expected or snapshots > 4 or not tenant_and_latest), '[]'::jsonb) as failed_cases from results;
